// extraToolFactory 组合平台工具 + 该 agent 挂载的 MCP server 工具。
func extraToolFactory(pt *biz.PlatformTools, mcpRepo biz.McpDataRepo, mcpBuilder *agentkit.McpClientBuilder) agentkit.ExtraToolFactory {
	return func(ctx context.Context, sessionID string, a *po.Agent) ([]tool.BaseTool, error) {
		var out []tool.BaseTool
		// 平台工具（所有 agent 可用；编排类 agent 经 prompt 引导使用）
		pts, err := pt.Tools()
		if err == nil {
			out = append(out, pts...)
		}
		// MCP server 工具（按 mcp_ids 挂载）
		var mcpIDs []int64
		if len(a.McpIDs) > 0 {
			_ = json.Unmarshal(a.McpIDs, &mcpIDs)
		}
		for _, id := range mcpIDs {
			srv, err := mcpRepo.GetServer(ctx, id)
			if err != nil || srv.Status != "enabled" {
				continue
			}
			tools, err := mcpBuilder.BuildTools(ctx, srv)
			if err != nil {
				continue // 单点失败不阻塞整个 agent
			}
			out = append(out, tools...)
		}
		return out, nil
	}
}

// newChainAgentRunner 规则链 Agent 节点执行器：以节点输入运行指定 Agent，返回最终文本。
func newChainAgentRunner(agentManager *agentkit.Manager) nodes.AgentRunner {
	return func(ctx context.Context, agentKey, prompt string) (string, error) {
		ag, err := agentManager.Get(ctx, agentKey)
		if err != nil {
			return "", fmt.Errorf("agent 不可用: %w", err)
		}
		res, err := agentkit.Run(ctx, ag, nil, &agentkit.Input{Text: prompt}, nil, nil, "system", "chain-"+agentKey)
		if err != nil {
			return "", err
		}
		return res.Text, nil
	}
}

